# Synthetic bounded workflow

Use only the supplied in-memory world.

```tsg-workflow
{
  "version": 1,
  "steps": [
    {
      "id": "a001_66087",
      "kind": "effect",
      "op": "read",
      "resource": "/synthetic/phase10/66087cdda1/selector",
      "out": "selector_66087"
    },
    {
      "id": "a007_66087",
      "kind": "if",
      "eq": [
        {
          "var": "selector_66087"
        },
        "locked"
      ],
      "then": [
        {
          "id": "a003_66087",
          "kind": "if",
          "eq": [
            true,
            true
          ],
          "then": [
            {
              "id": "a002_66087",
              "kind": "effect",
              "op": "read",
              "resource": "/synthetic/phase10/66087cdda1/secret",
              "out": "payload_66087"
            }
          ],
          "else": []
        }
      ],
      "else": [
        {
          "id": "a005_66087",
          "kind": "repeat",
          "count": 2,
          "body": [
            {
              "id": "a004_66087",
              "kind": "call",
              "fn": "local_66087"
            }
          ]
        },
        {
          "id": "a006_66087",
          "kind": "effect",
          "op": "read",
          "resource": "/synthetic/phase10/66087cdda1/stage",
          "out": "payload_66087"
        }
      ]
    },
    {
      "id": "a008_66087",
      "kind": "effect",
      "op": "write",
      "resource": "/synthetic/phase10/66087cdda1/out",
      "value": {
        "var": "payload_66087"
      }
    },
    {
      "id": "a010_66087",
      "kind": "repeat",
      "count": 0,
      "body": [
        {
          "id": "a009_66087",
          "kind": "effect",
          "op": "emit",
          "resource": "/synthetic/phase10/66087cdda1/cold",
          "value": "kahikatea_101"
        }
      ]
    }
  ],
  "functions": {
    "local_66087": [
      {
        "id": "a011_66087",
        "kind": "effect",
        "op": "write",
        "resource": "/synthetic/phase10/66087cdda1/stage",
        "value": "kahikatea_101"
      }
    ]
  }
}
```

